  selector: 'app-multi-list',
  templateUrl: './multi-list.component.html'
})
export class MultiListComponent {
  // Sample list items
  items = [
    { id: 0, name: 'List Item 1', content: '' },
    { id: 1, name: 'List Item 2', content: '' }
  ];

  addItem() {
    const newItem = { id: this.items.length, name: '', content: '' };
    this.items.push(newItem);
