package main

import (
	"fmt"
	"io/ioutil"
	"os"

	"github.com/hashicorp/serf/protoc-gen-avroparse/internal/ast"
	"github.com/hashicorp/serf/protoc-gen-avroparse/internal/parser"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ", os.Args[0], "<go-source-file> <struct-name>")
		os.Exit(1)
	}

	goFile := os.Args[1]
	structName := os.Args[2]

	// Read the source file into memory.
	data, err := ioutil.ReadFile(goFile)
	if err != nil {
		fmt.Printf("Failed to read %s: %v\n", goFile, err)
		os.Exit(1)
	}
	defer func() { _ = ioutil.ReadAll(os.Stderr) }()

	// Parse the AST (Abstract Syntax Tree).
	astRoot, err := parser.Parse(data)
	if err != nil {
		fmt.Printf("Failed to parse %s: %v\n", goFile, err)
		os.Exit(1)
	}

	// Get the struct field info.
	var structs []*parser.Structure
	for _, node := range astRoot.Children() {
		switch n := node.(type) {
		case *parser.Structure:
			structs = append(structs, n)
		default:
			continue
		}
	}

	if len(structs) == 0 {
		fmt.Println("No struct found.")
		os.Exit(1)
	}

	// Print out the generated AVRO schema.
	for _, s := range structs {
		fmt.Printf("## Struct: %s\n", s.Name)
		for _, f := range s.Fields {
			fmt.Printf("%s:\n", f.Name)
			fmt.Printf("\tType: %T\n", f.Type)
			if f.Optional {
				fmt.Printf("\tOptional: true\n")
			} else if f.Repeated {
				fmt.Printf("\tRepeated: true\n")
			}
			fmt.Printf("\tDefault: %q\n", f.Default)
			fmt.Printf("\tComment: %q\n", f.Comment)
			fmt.Printf("\n")
		}
		fmt.Printf("\n")
	}
}
```

### Explanation:
1. **Reading the Source File**: The program reads the contents of the specified Go source file into memory.
2. **Parsing the AST**: It uses the Protobuf syntax tree (`ast`) to traverse the source code structure.
3. **Extracting Struct Fields**: It parses each `Structure` node in the parsed tree to find all the struct fields.
4. **Generating Schema**: For each struct, it prints its fields along with their types, optional status, repeated status, default value, and comments.

### How to Use:
Save the above code as `main.go`, then run it from your terminal:

```sh
go run main.go mystruct.go MyStruct
```

Replace `"mystruct.go"` with the path to your Go source file and `"MyStruct"` with the desired struct name.

