        } catch (InputMismatchException e) {
            System.err.println("Invalid input detected. Please enter numeric values only.");
            return; // Exit the program gracefully
        }

        // If no exceptions were caught, continue with other logic
        System.out.println("Processing completed successfully.");
    }
